const tokenInfo = $json;
const body = $('상담 Webhook').item.json.body || {};
const GOOGLE_CLIENT_ID = '188637268860-9hj2af4bt8esn506bf5bqs72qnbu0qjs.apps.googleusercontent.com';
const 유효함 = tokenInfo && !tokenInfo.error && tokenInfo.aud === GOOGLE_CLIENT_ID && tokenInfo.email && String(tokenInfo.email_verified) === 'true';
if (!유효함) { throw new Error('로그인 확인에 실패했습니다.'); }
const history = Array.isArray(body.history) ? body.history.slice(-20) : [];
const message = String(body.message || '').trim().slice(0, 600);
if (!message) { throw new Error('메시지가 비어있습니다.'); }
const pastProjects = Array.isArray(body.pastProjects) ? body.pastProjects.slice(0, 5) : [];
return [{ json: { history, message, pastProjects } }];

const history = $json.history;
const message = $json.message;
const historyText = history.map(h => `${h.role === 'user' ? '고객' : '상담원'}: ${h.text}`).join('\n');
const pastProjects = $json.pastProjects || [];
const pastText = pastProjects.length
  ? pastProjects.map(p => `- ${p.title || '(제목 미정)'} (${p.form || '쇼츠'}, 상태: ${p.status || '-'})`).join('\n')
  : '(이 고객은 이전에 신청한 적이 없습니다 - 첫 이용 고객)';
return [{ json: { historyText, message, pastText } }];

