const raw = ($json.output || '').replace(/```json/g, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { reply: raw || '죄송해요, 다시 한번 말씀해주시겠어요?', mode: null, collected: {}, complete: false }; }
return [{ json: {
  ok: true,
  reply: parsed.reply || '',
  mode: parsed.mode || null,
  collected: parsed.collected || {},
  complete: !!parsed.complete
} }];
